require_once '../includes/auth.php';require_once '../includes/functions.php';if(isTenantUser())requireTenant();global $conn;
$cols=[];$q=$conn->query("SHOW COLUMNS FROM pppoe_servers");while($x=$q->fetch_assoc())$cols[]=$x['Field'];$has=fn($c)=>in_array($c,$cols,true);$tid=getCurrentTenantId();$where=[];$p=[];$t='';if($has('tenant_id')&&$tid){$where[]='s.tenant_id=?';$p[]=$tid;$t.='i';}
$sql="SELECT s.* FROM pppoe_servers s".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY s.id DESC LIMIT 200";$st=$conn->prepare($sql);if($p)$st->bind_param($t,...$p);$st->execute();$rows=$st->get_result();
function pv($r,$a,$d=''){foreach($a as $c)if(array_key_exists($c,$r))return $r[$c];return $d;}
