<?php require '../includes/header.php';?><div class="page-content"><div class="page-header"><div><h1>PPPoE Servers</h1><p>Manage PPPoE server profiles.</p></div><a class="btn btn-primary" href="add.php">+ Add Server</a></div><div class="card"><div style="overflow:auto"><table class="table"><thead><tr><th>Name</th><th>Router</th><th>Interface</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows->num_rows):?><tr><td colspan="5" style="text-align:center;padding:30px">No PPPoE servers found.</td></tr><?php else:while($r=$rows->fetch_assoc()):?><tr><td><?=e(pv($r,['name','server_name'],(string)$r['id']))?></td><td><?=e(pv($r,['router_id']))?></td><td><?=e(pv($r,['interface']))?></td><td><?=e(ucfirst(pv($r,['status'],'active')))?></td><td><a class="btn btn-secondary" href="edit.php?id=<?=$r['id']?>">Edit</a></td></tr><?php endwhile;endif;?></tbody></table></div></div></div><?php require '../includes/footer.php';?>